import csv

# Analyze the distinct 'base patterns' in raw_reason_text
# These are the core defect description templates before noise/duplicates
with open('/app/data/test_center_logs.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    reasons = []
    for row in reader:
        reasons.append(row['raw_reason_text'])

# Find the base atomic phrases that appear
import re

# Count frequency of key Chinese phrases
cn_phrases = {}
en_phrases = {}
for r in reasons:
    # Look for Chinese segments
    for seg in re.split(r'[/;;&+]+', r):
        seg = seg.strip()
        if seg:
            # Remove trailing noise words
            seg_clean = re.sub(r'\s+(NG|OK了|重测过|已处理|有问题|疑似|浮高|返修|换掉|可能|不稳定|确认|挂|接触不好|rework|retest|intermittent|clean)$', '', seg.strip())
            seg_clean = seg_clean.strip()
            if seg_clean:
                if any('\u4e00' <= c <= '\u9fff' for c in seg_clean):
                    cn_phrases[seg_clean] = cn_phrases.get(seg_clean, 0) + 1
                else:
                    en_phrases[seg_clean] = en_phrases.get(seg_clean, 0) + 1

print('=== Top 40 Chinese phrases ===')
for k, v in sorted(cn_phrases.items(), key=lambda x: -x[1])[:40]:
    print(f'  {v:5d}: {k}')

print()
print('=== Top 40 English phrases ===')
for k, v in sorted(en_phrases.items(), key=lambda x: -x[1])[:40]:
    print(f'  {v:5d}: {k}')
